('wizard_necromancer','kingdom_of_bones','{"id":"kingdom_of_bones","name":"پادشاهی استخوان‌ها","en":"Kingdom of Bones","unlockLevel":7,"type":"legion_offense_buff","target":"تمام اعضای زنده لژیون","manaCostPercent":11,"cooldownTurns":5,"durationTurns":3,"description":"فرمان جنگ صادر می‌شود؛ برای ۳ نوبت حمله اعضای لژیون، احتمال ضربه بحرانی و توان شکستن دفاع افزایش می‌یابد. کشتن دشمن توسط عضو لژیون ۱ روح تولید می‌کند؛ حداکثر ۲ روح در هر بار اجرا.","bossRules":"اثر فقط بر اعضای زنده لژیون است و با شکوفایی استخوان از نظر نقش متفاوت است.","upgradeRanks":6,"upgrades":[{"rank":2,"pointsRequired":1,"effect":"رتبه ۲: شدت اثر اصلی 108٪ مقدار پایه؛ فرمان جنگ صادر می‌شود؛ برای ۳ نوبت حمله اعضای لژیون، احتمال ضربه بحرانی و توان شکستن دفاع افزایش می‌یابد. کشتن دشمن توسط عضو لژیون ۱ روح تولید می‌کند؛ حداکثر ۲ روح در هر بار اجرا.","bonus":"ارتقای اختصاصی پادشاهی استخوان‌ها: افزایش کنترل‌شده اثر اصلی."},{"rank":3,"pointsRequired":2,"effect":"رتبه ۳: شدت اثر اصلی ۱۱۶٪ مقدار پایه؛ هزینه مانا بدون تغییر.","bonus":"ارتقای اختصاصی پادشاهی استخوان‌ها: افزایش کنترل‌شده اثر پایدار."},{"rank":4,"pointsRequired":3,"effect":"رتبه ۴: شدت اثر اصلی ۱۲۴٪ مقدار پایه؛ یک بهبود اختصاصی در تعامل مهارت.","bonus":"ارتقای اختصاصی پادشاهی استخوان‌ها: افزایش کنترل‌شده اثر ثانویه."},{"rank":5,"pointsRequired":4,"effect":"رتبه ۵: شدت اثر اصلی ۱۳۲٪ مقدار پایه؛ هزینه مانا ۱ واحد درصد کمتر.","bonus":"ارتقای اختصاصی پادشاهی استخوان‌ها: افزایش کنترل‌شده اثر تخصصی."},{"rank":6,"pointsRequired":5,"effect":"رتبه ۶: شدت اثر اصلی ۱۴۰٪ مقدار پایه؛ مدت اثر +۱ نوبت، اگر مهارت مدت‌دار باشد.","bonus":"ارتقای اختصاصی پادشاهی استخوان‌ها: افزایش کنترل‌شده اثر پیشرفته."},{"rank":7,"pointsRequired":6,"effect":"رتبه ۷: شدت اثر اصلی ۱۵۰٪ مقدار پایه؛ بازده ثانویه مهارت +۱۵٪. محدودیت‌های هدف و ظرفیت همچنان پابرجاست.","bonus":"ارتقای اختصاصی پادشاهی استخوان‌ها: افزایش کنترل‌شده اثر نهایی."}]}'::jsonb),
